package net.civeira.phylax.feature.observe.observedissuecomment.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AuthorNameVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property author name of observed issue comment ")
  void test_author_name_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> AuthorNameVO.tryFrom(null));
    Assertions.assertEquals("one", AuthorNameVO.from("one").getAuthorName());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> AuthorNameVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", AuthorNameVO.from("one").toString());
  }
}
